BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || v.patch
FROM (VALUES
  ('g-kentei-h-q18', '{"point": "「同じ重みを時刻ごとに展開してから、出力側から過去へ誤差をさかのぼらせて各時刻の勾配をまとめる」なら、BPTT。"}'::jsonb),
  ('g-kentei-h-q19', '{"point": "「誤差の合図を掛け算で薄めず、足し算だけで保ったまま運ぶ専用の通路」なら、CEC。"}'::jsonb),
  ('g-kentei-j-q37', '{"point": "「ニューロン1つが単一の数値ではなく、向き・大きさを持つベクトルとして情報を運ぶ」なら、Capsule Network。", "usecase": "実務での主流採用はまだ少ないが、CNNのプーリングが部分の位置関係を失いやすいという弱点を克服しようとした発想として、技術トレンドの理解を試す文脈で問われる。"}'::jsonb),
  ('g-kentei-j-q9', '{"point": "「掛け算する傾きの上限が大きいほど、逆伝播で勾配は縮みにくい」なら、tanh(上限1)の方がシグモイド(上限0.25)より勾配消失がやや起きにくい。", "usecase": "活性化関数を選ぶときの判断材料の一つ。深い層ほど勾配消失に弱くなるため、傾きの上限が大きい・消えにくい活性化関数（tanhやReLU）が好まれてきた歴史的経緯につながる。"}'::jsonb),
  ('g-kentei-k-q20', '{"point": "「行列の行と列をまるごと入れ替える」なら、転置。", "usecase": "逆伝播で誤差を前の層へ伝えるとき、重み行列を転置してから掛け算する場面が必ず出てくる。行列どうしの掛け算ができるようサイズ（行数・列数）を合わせるための基本操作として押さえておく。"}'::jsonb),
  ('g-kentei-b-q24', '{"think": "なぜ前の出力を次に持ち越すと、順番のあるデータをうまく扱えるのかがカギ。文章や時系列は、今の値だけでなく「それより前に何があったか」で意味が決まる。たとえば「銀行の（　）に並んだ」の空欄は、直前の文脈が分からないと埋められない。もし各単語をバラバラに独立して処理したら、この「それより前の文脈」の情報がどこにも残らない。そこで回帰結合層は、ある時点の出力を次の時点の入力に混ぜて渡す。すると各時点の処理に「それまでの文脈」が乗った状態で伝わっていき、順番そのものが意味を持つデータを扱えるようになる。画像の局所特徴を拾う畳み込み層には、この「前を持ち越す」仕組みがない。"}'::jsonb),
  ('g-kentei-c-q27', '{"think": "なぜ一度ベクトルに凝縮してから作り直す、という二段構えが要るのかがカギ。翻訳のように入力と出力で言語も長さも違う系列を扱うとき、単語を1対1で置き換えるだけでは語順も文法も揃わずうまくいかない。そこでエンコーダが入力文を先頭から順に読み込み、文全体の意味を1本のベクトルへと凝縮する。このベクトルには、個々の単語ではなく「文全体が何を言っているか」が畳み込まれている。デコーダはこのベクトルだけを手がかりに、出力側の言語の文法や語順に従って1語ずつ新しい系列を組み立てていく。入力の長さと出力の長さが一致していなくても、間に挟むのが固定長のベクトルなので問題にならない。入力をそのまま復元するオートエンコーダとは、ここから先に何を作るかが違う。"}'::jsonb),
  ('g-kentei-d-q13', '{"think": "なぜ「赤=1、青=2、緑=3」のように整数を割り振るだけではまずいのかがカギ。機械学習のモデルの多くは、数字の大小や差を「量」として扱う。整数を割り振ると、モデルは「緑(3)は赤(1)よりずっと大きい」「青(2)は赤と緑のちょうど中間」のように、本来存在しない大小関係や距離を勝手に読み取ってしまう。赤・青・緑には本来そういう順序や距離は無いのに、数値化しただけでモデルには「順序があるように」見えてしまうのが問題。そこで各カテゴリに1つずつ専用の場所（次元）を用意し、あてはまる場所だけ1、残りは全部0にする。こうすればどのカテゴリも他のカテゴリと同じ距離になり、余計な大小関係をモデルに読み取らせずに済む。"}'::jsonb),
  ('g-kentei-q11', '{"think": "見分けるカギは「正解ラベル(お手本の答え)を使うかどうか」。4つを順に当てはめる。主成分分析(PCA)は、正解ラベルを一切使わずデータの散らばりだけを見て軸を決める→教師なし。k-means法も、正解ラベルなしで距離が近いデータどうしを自動でグループ分けする→教師なし。ロジスティック回帰は「名前は回帰だが中身は分類」の代表選手で、入力と正解ラベルのペアを見て学習する→教師あり。ランダムフォレストも同様に、正解ラベル付きのデータで木を育てて多数決する→教師あり。取り違えやすいのは、ロジスティック回帰を名前だけで数値予測(教師あり)の仲間だと見落としたり、ランダムフォレストを「たくさんの木でデータをまとめている」と誤解して教師なし側に入れてしまうこと。名前や処理のイメージではなく、必ず「学習のときに正解ラベルを与えているか」で判定する。"}'::jsonb)
) AS v(source_ref, patch)
WHERE q.source_ref = v.source_ref
  AND q.subject_id IN (SELECT id FROM public.subjects WHERE slug LIKE 'g-kentei%');

COMMIT;
